#
# Unit tests for the Julia kernel ports. Expected values are literals
# generated by running the LIVE Numba kernels (NUMBA_NUM_THREADS=1) via
# julia/tools/gen_unit_literals.py — cross-language parity on small cases,
# independent of the big golden corpus. The corpus-level gates live in
# equivalence_runner.jl, wired into CI by .github/workflows/julia.yml.

using Test
using PygeofloodKernels

@testset "process_cells" begin
    @testset "hand-computed crop (mirrors rust/src/cells.rs tests)" begin
        hand = Float32[0.0 0.5 1.0 NaN]
        catchments = fill(Int32(10), 1, 4)
        slope = zeros(Float32, 1, 4)
        hyd = [Int32(10) 0]
        heights = [0.0, 1.0, 2.0]
        counts, surface, bed, volume = process_cells(
            hand, catchments, slope, hyd, heights, 2.0)
        @test counts == [1; 2; 3;;]          # NaN cell never active
        @test surface == [2.0; 4.0; 6.0;;]
        @test bed == [2.0; 4.0; 6.0;;]       # slope 0 -> bed area == surface
        @test volume == [0.0; 3.0; 9.0;;]
        @test eltype(counts) == Int32
        @test eltype(surface) == Float32
    end

    @testset "insertion-index fold for out-of-table catchments" begin
        hand = Float32[0.0 0.5 1.0 NaN]
        catchments = fill(Int32(15), 1, 4)   # 10 < 15 < 20 -> slot 1 (0-based)
        slope = zeros(Float32, 1, 4)
        hyd = [Int32(10) 0; Int32(20) 1]
        counts, surface, bed, volume = process_cells(
            hand, catchments, slope, hyd, [0.0, 1.0, 2.0], 2.0)
        @test counts == [0 1; 0 2; 0 3]
        @test iszero(surface[:, 1]) && iszero(bed[:, 1]) && iszero(volume[:, 1])
    end

    @testset "near-zero inclusion at |hand| <= 1e-8" begin
        hand = Float32[0.0 1e-9 -1e-9 1e-8 -1e-8 1.01e-8 0.5]
        catchments = fill(Int32(10), 1, 7)
        slope = zeros(Float32, 1, 7)
        hyd = [Int32(10) 0]
        counts, surface, bed, volume = process_cells(
            hand, catchments, slope, hyd, [0.0], 1.0)
        @test counts == [5;;]
        @test surface == [5.0;;]
        @test volume == [0.0;;]              # stage 0 -> zero-depth deltas
    end

    @testset "precision flags round through Float32 per update" begin
        # volume_f32 requires Float32 hand AND heights; delta and cell_area are
        # each truncated to f32 before the multiply
        hand = Float32[0.1;;]
        catchments = fill(Int32(3), 1, 1)
        slope = zeros(Float32, 1, 1)
        hyd = [Int32(3) 0]
        counts, surface, bed, volume = process_cells(
            hand, catchments, slope, hyd, Float32[1.0], Float32(1.1))
        @test counts == [1;;]
        @test surface == [Float32(1.1);;]    # f64 1.1 + 0 -> f32(1.1)
        @test volume[1, 1] ==
              Float32(Float32(1.0) - Float32(0.1)) * Float32(1.1)
    end

    @testset "out-of-table active catchment errors" begin
        hand = Float32[-0.5;;]   # negative hand is active at stage 0
        slope = zeros(Float32, 1, 1)
        @test_throws ErrorException process_cells(
            hand, fill(Int32(100), 1, 1), slope, [Int32(10) 0], [0.0], 1.0)
        # an inactive out-of-table cell (hand above every stage) is fine
        counts, _, _, _ = process_cells(
            Float32[5.0;;], fill(Int32(100), 1, 1), slope, [Int32(10) 0],
            [0.0], 1.0)
        @test iszero(counts)
    end

    @testset "hydroid table validation" begin
        hand = Float32[0.5;;]
        catchments = fill(Int32(10), 1, 1)
        slope = zeros(Float32, 1, 1)
        @test_throws ArgumentError process_cells(
            hand, catchments, slope, [Int32(20) 0; Int32(10) 1], [0.0], 1.0)
        @test_throws ArgumentError process_cells(
            hand, catchments, slope, [Int32(10) 0; Int32(0) 1], [0.0], 1.0)
    end

    @testset "empty heights and empty grids" begin
        hand = Float32[0.5 0.6]
        catchments = fill(Int32(10), 1, 2)
        slope = zeros(Float32, 1, 2)
        hyd = [Int32(10) 0]
        counts, surface, bed, volume = process_cells(
            hand, catchments, slope, hyd, Float64[], 1.0)
        @test size(counts) == (0, 1)
        empty_grid = Matrix{Float32}(undef, 0, 4)
        counts, surface, bed, volume = process_cells(
            empty_grid, Matrix{Int32}(undef, 0, 4), Matrix{Float32}(undef, 0, 4),
            hyd, [0.0, 1.0], 1.0)
        @test size(counts) == (2, 1)
        @test iszero(counts) && iszero(surface)
    end

    @testset "chunk partition covers every row exactly (pure function of rows)" begin
        for rows in [0, 1, 31, 32, 33, 67, 999, 2000]
            nchunks = clamp(rows, 1, PROCESS_CELLS_MAX_CHUNKS)
            covered = Int[]
            for c in 0:nchunks-1
                start0, stop0 = PygeofloodKernels._row_range(rows, nchunks, c)
                append!(covered, start0:stop0-1)
            end
            @test covered == collect(0:rows-1)
        end
    end

    @testset "repeated calls are identical (fold is order-deterministic)" begin
        hand = randn(Float32, 64, 32) .* 5
        catchments = rand(1:3, 64, 32)
        slope = abs.(randn(Float32, 64, 32))
        hyd = hcat(Int32[1, 2, 3], Int32[0, 1, 2])
        heights = collect(0.0:0.25:2.0)
        a = process_cells(hand, catchments, slope, hyd, heights, 1.5)
        b = process_cells(hand, catchments, slope, hyd, heights, 1.5)
        @test a == b
    end
end

@testset "binary_search" begin
    arr = [1.0, 3.0, 5.0, 7.0, 9.0]
    @test binary_search(arr, 1.0) == 0      # first
    @test binary_search(arr, 9.0) == 4      # last
    @test binary_search(arr, 5.0) == 2      # middle
    @test binary_search(arr, 0.0) == -1     # below range
    @test binary_search(arr, 10.0) == -1    # above range
    @test binary_search(arr, 4.0) == -1     # between
    @test binary_search(Float64[], 1.0) == -1
end

@testset "jit_inun" begin
    @testset "stage lookup, wet/dry, and sentinel (literals from Numba)" begin
        hand = Float32[1.0 2.0 9.0; 0.5 6.0 3.0]
        segc = Int32[1 2 99; 2 1 7]
        hydroids = [1.0, 2.0, 7.0]
        stage = [5.0, 3.0, 10.0]
        inun = jit_inun(hand, segc, hydroids, stage)
        @test inun[1, 1] == 4.0f0
        @test inun[1, 2] == 1.0f0
        @test isnan(inun[1, 3])              # unmapped -> sentinel -> dry
        @test inun[2, 1] == 2.5f0
        @test isnan(inun[2, 2])              # stage <= hand -> dry
        @test inun[2, 3] == 7.0f0
        @test eltype(inun) == Float32
    end

    @testset "sorted-hydroid precondition is unvalidated (bug-for-bug)" begin
        hand = Float32[1.0;;]
        segc = fill(Int32(2), 1, 1)
        # catchment 2 exists in the table but the stages are unsorted; Numba's
        # binary_search validates nothing and silently returns the
        # insertion-point stage (3.0) — reproduce that verbatim
        inun = jit_inun(hand, segc, [1.0, 2.0], [5.0, 3.0])  # unsorted table
        @test inun[1, 1] == Float32(3.0 - 1.0)   # 2.0: stage taken unvalidated
    end
end

@testset "jit_binary_hand" begin
    @testset "flowline center, uniform dem (literals from Numba)" begin
        dem = fill(10.0f0, 3, 3)
        dem[2, 2] = 4.0f0
        fl = zeros(Int16, 3, 3)
        fl[2, 2] = 1
        bh = jit_binary_hand(dem, fl, -32768.0)
        @test bh == [0 0 0; 0 1 0; 0 0 0]    # neighbors drain to lower stream -> 0
    end

    @testset "NaN dem cell stays 1 in the kernel (driver fixes it later)" begin
        dem = fill(7.5f0, 4, 4)
        dem[1, 1] = NaN
        fl = zeros(Int16, 4, 4)
        fl[4, 4] = 1
        bh = jit_binary_hand(dem, fl, -32768.0)
        @test all(bh .== 1)
    end

    @testset "flowline cell is always 1" begin
        dem = fill(2.0f0, 2, 2)
        fl = zeros(Int16, 2, 2)
        fl[1, 1] = 1
        bh = jit_binary_hand(dem, fl, -32768.0)
        @test bh[1, 1] == 1                  # allocation == dem -> not less
    end
end
